CREATE OR REPLACE FUNCTION median_acceptance_hours(job_category VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
  result_val NUMERIC;
BEGIN
  SELECT COALESCE(
    PERCENTILE_CONT(0.5) WITHIN GROUP (
      ORDER BY EXTRACT(EPOCH FROM (accepted_at - invited_at)) / 3600
    ),
    0.00
  )
  INTO result_val
  FROM job_invitations
  WHERE job_invitations.job_category = median_acceptance_hours.job_category
    AND accepted_at IS NOT NULL;

  RETURN ROUND(result_val, 2);
END;
$$ LANGUAGE plpgsql;

SELECT median_acceptance_hours('delivery') AS result;

