CREATE OR REPLACE FUNCTION median_acceptance_hours(p_job_category VARCHAR)
RETURNS NUMERIC AS $$
BEGIN
    RETURN (
        SELECT
            ROUND(
                PERCENTILE_CONT(0.5) WITHIN GROUP (
                    ORDER BY
                            EXTRACT(
                                EPOCH FROM (accepted_at - invited_at)
                                )/3600
                            )::numeric
                    , 2) AS result
        FROM job_invitations 
        WHERE accepted_at IS NOT NULL AND job_category = p_job_category
        );
END;
$$ LANGUAGE PLPGSQL;

SELECT median_acceptance_hours('delivery') AS result;
